package com.clara.workspace.runtime;
import com.clara.kernel.*;import com.clara.workspace.api.*;import java.nio.charset.StandardCharsets;import java.nio.file.*;import java.util.*;import org.junit.*;import org.junit.rules.TemporaryFolder;import static org.junit.Assert.*;
public class DefaultWorkspaceTextServiceTest {@Rule public final TemporaryFolder folder=new TemporaryFolder();private Path root;private WorkspacePolicy policy;private WorkspaceRef workspace;private DefaultWorkspaceTextService service;
 @Before public void setUp()throws Exception{root=folder.newFolder("workspace").toPath();policy=new WorkspacePolicy(new HashSet<String>(Arrays.asList(".txt",".java")),Collections.<String>emptySet(),Collections.<String>emptySet(),20,10000,50000,false);workspace=new WorkspaceRef("w","t","run",root.toAbsolutePath(),WorkspaceAccessMode.PREVIEW_WRITE);service=new DefaultWorkspaceTextService(new FileSystemWorkspaceReader(policy),policy);}
 @Test public void searchIsStableNonOverlappingAndReportsOriginalOffsets()throws Exception{Files.write(root.resolve("b.txt"),"xx AA aa".getBytes(StandardCharsets.UTF_8));Files.write(root.resolve("a.txt"),"aaaa\nAa".getBytes(StandardCharsets.UTF_8));TextSearchRequest request=new TextSearchRequest(TextMatchMode.LITERAL,"aa",true,10,10);TextSearchResult first=service.search(workspace,request),second=service.search(workspace,request);assertFalse(first.isTruncated());assertEquals(5,first.getMatches().size());assertEquals("a.txt",first.getMatches().get(0).getRelativePath());assertEquals(0,first.getMatches().get(0).getStart());assertEquals(2,first.getMatches().get(1).getStart());assertEquals(2,first.getMatches().get(2).getLine());assertEquals(1,first.getMatches().get(2).getColumn());assertEquals(first.getMatches().get(0).getMatchId(),second.getMatches().get(0).getMatchId());assertEquals(first.getQueryFingerprint(),second.getQueryFingerprint());}
 @Test public void preservesUtf8BomAndTreatsReplacementLiterally()throws Exception{byte[] body="value=x\n".getBytes(StandardCharsets.UTF_8),bytes=new byte[body.length+3];bytes[0]=(byte)239;bytes[1]=(byte)187;bytes[2]=(byte)191;System.arraycopy(body,0,bytes,3,body.length);Files.write(root.resolve("a.txt"),bytes);TextSearchRequest request=new TextSearchRequest(TextMatchMode.LITERAL,"x",false,10,10);TextSearchResult found=service.search(workspace,request);Map<String,String> hashes=Collections.singletonMap("a.txt",found.getMatches().get(0).getFileHash());TextEditSpec edit=new TextEditSpec(request,TextEditAction.REPLACE_MATCH,"$1\\tail",Collections.<String>emptySet(),1,2,hashes);ChangeSet set=service.replace(workspace,edit);byte[] result=set.getChanges().get(0).getContent();assertArrayEquals(new byte[]{(byte)239,(byte)187,(byte)191},Arrays.copyOf(result,3));assertEquals("value=$1\\tail\n",new String(result,3,result.length-3,StandardCharsets.UTF_8));}
 @Test public void rejectsTruncatedEditsStaleHashesAndUnsafeRegex()throws Exception{Files.write(root.resolve("a.txt"),"x x".getBytes(StandardCharsets.UTF_8));final TextSearchRequest limited=new TextSearchRequest(TextMatchMode.LITERAL,"x",false,10,1);assertTrue(service.search(workspace,limited).isTruncated());assertCode(ErrorCodes.WORKSPACE_CONFLICT,new Runnable(){public void run(){service.deleteText(workspace,new TextEditSpec(limited,TextEditAction.DELETE_MATCH,"",Collections.<String>emptySet(),1,2));}});final TextSearchRequest full=new TextSearchRequest(TextMatchMode.LITERAL,"x",false,10,10);assertCode(ErrorCodes.WORKSPACE_CONFLICT,new Runnable(){public void run(){service.replace(workspace,new TextEditSpec(full,TextEditAction.REPLACE_MATCH,"y",Collections.<String>emptySet(),2,2,Collections.singletonMap("a.txt","stale")));}});assertCode(ErrorCodes.REGEX_UNSUPPORTED,new Runnable(){public void run(){service.search(workspace,new TextSearchRequest(TextMatchMode.SAFE_REGEX,"x+",false,10,10));}});}
 private static void assertCode(String code,Runnable action){try{action.run();fail("expected "+code);}catch(ClaraException e){assertEquals(code,e.getError().getCode());}}
}
